/* УВЕДОМЛЕНИЯ В МЕССЕНДЖЕРЫ: Telegram, VK Teams или любой свой адрес (webhook — например,
   корпоративный посредник к eXpress или Mattermost).
   1) По кнопке: отправить выделенную таблицу или текст.
   2) По правилам, пока книга открыта: «если в столбце Остаток меньше 10 — написать
      „Заканчивается {Товар}, осталось {Остаток}“». Плагин фоновый: правила работают и без
      открытой панели. О каждой строке сообщает один раз, пока условие не перестанет выполняться.
   Токен бота хранится только в этом браузере (хранилище «тайно») и в файл плагина не попадает. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const УСЛОВИЯ = ['меньше', 'меньше или равно', 'больше', 'больше или равно', 'равно', 'не равно', 'содержит', 'пусто', 'дата не позже чем через N дней'];
const ДЕНЬ = 86400000;
const сегодня = () => { const d = new Date(); return Math.round((Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) - Date.UTC(1899, 11, 30)) / ДЕНЬ); };
const ДМГ = д => { const x = new Date(Date.UTC(1899, 11, 30) + д * ДЕНЬ); return String(x.getUTCDate()).padStart(2, '0') + '.' + String(x.getUTCMonth() + 1).padStart(2, '0') + '.' + x.getUTCFullYear(); };
const эк = т => String(т).replace(/[&<>]/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;'}[c]));

/* --- настройки канала --- */
function канал(){
  const п = параметры({});
  const вид = п.канал || хранилище.взять('канал', 'Telegram');
  const токен = (п.токен && String(п.токен).trim()) || хранилище.взять('токен', '');
  const чат = (п.чат && String(п.чат).trim()) || хранилище.взять('чат', '');
  const адрес = (п.адрес && String(п.адрес).trim()) || хранилище.взять('адрес', '');
  const шаблон = п.шаблонТела || хранилище.взять('шаблонТела', '{"text": {текст}}');
  return {вид, токен, чат, адрес, шаблон};
}
async function отправить(текст, {моноширинно = false} = {}){
  const к = канал();
  let ответ;
  try {
    if(к.вид === 'Telegram'){
      if(!к.токен || !к.чат) return {ок: false, почему: 'нет токена бота или номера чата'};
      const база = (к.адрес || 'https://api.telegram.org').replace(/\/+$/, '');
      const тело = 'chat_id=' + encodeURIComponent(к.чат) + '&text=' + encodeURIComponent(моноширинно ? '<pre>' + эк(текст) + '</pre>' : текст)
        + (моноширинно ? '&parse_mode=HTML' : '') + '&disable_web_page_preview=true';
      /* «простой» запрос без предварительного OPTIONS: тип — форма */
      ответ = await запрос(база + '/bot' + к.токен + '/sendMessage', {метод: 'POST', заголовки: {'Content-Type': 'application/x-www-form-urlencoded'}, тело});
      if(ответ.ок && ответ.тело && ответ.тело.ok) return {ок: true};
      return {ок: false, почему: (ответ.тело && ответ.тело.description) || ('код ' + ответ.код)};
    }
    if(к.вид === 'VK Teams'){
      if(!к.токен || !к.чат || !к.адрес) return {ок: false, почему: 'нужны адрес Bot API, токен и чат'};
      const база = к.адрес.replace(/\/+$/, '');
      ответ = await запрос(база + '/messages/sendText?token=' + encodeURIComponent(к.токен) + '&chatId=' + encodeURIComponent(к.чат) + '&text=' + encodeURIComponent(текст));
      if(ответ.ок && ответ.тело && ответ.тело.ok) return {ок: true};
      return {ок: false, почему: (ответ.тело && (ответ.тело.description || ответ.тело.error)) || ('код ' + ответ.код)};
    }
    /* свой адрес: тело по шаблону, {текст} — строкой JSON */
    if(!к.адрес) return {ок: false, почему: 'нет адреса webhook'};
    const тело = к.шаблон.split('{текст}').join(JSON.stringify(текст));
    ответ = await запрос(к.адрес, {метод: 'POST', заголовки: {'Content-Type': 'application/json'}, тело});
    return ответ.ок ? {ок: true} : {ок: false, почему: 'код ' + ответ.код + (ответ.текст ? ': ' + String(ответ.текст).slice(0, 120) : '')};
  } catch(e){
    return {ок: false, почему: e.message};
  }
}
function СохранитьНастройки(){
  const п = параметры({});
  хранилище.положить('канал', п.канал || 'Telegram');
  if(п.токен && String(п.токен).trim()){ хранилище.тайно('токен', String(п.токен).trim()); панель.поле('токен', ''); }
  хранилище.положить('чат', String(п.чат || '').trim());
  хранилище.положить('адрес', String(п.адрес || '').trim());
  хранилище.положить('шаблонТела', п.шаблонТела || '{"text": {текст}}');
  показатьНастройки();
  панель.сообщение('Настройки сохранены. Токен остаётся только в этом браузере.');
}
function показатьНастройки(){
  const к = канал();
  панель.список('состояние', [['Канал', к.вид], ['Токен', к.токен ? 'сохранён (…' + String(к.токен).slice(-4) + ')' : 'не задан'], ['Чат', к.чат || '—'],
    ['Правил', String(правила().length)], ['Последняя отправка', хранилище.взять('последняя', '—')]]);
}
async function Проверить(){
  const р = await отправить('Проверка связи из Пульс Таблиц: уведомления настроены.');
  if(р.ок){ хранилище.положить('последняя', new Date().toLocaleString('ru-RU')); показатьНастройки(); }
  панель.сообщение(р.ок ? 'Сообщение ушло — проверьте чат.' : 'Не отправилось: ' + р.почему + '.');
}
/* выделение — моноширинной таблицей */
async function ОтправитьВыделение(){
  const в = книга.выделение;
  if(!в || !в.область){ панель.сообщение('Выделите, что отправить.'); return; }
  const строки = (await лист(в.лист).прочитать(в.область)).slice(0, 60);
  const т = строки.map(р => р.map(v => v == null ? '' : typeof v === 'number' ? v.toLocaleString('ru-RU') : String(v)));
  const шир = [];
  т.forEach(р => р.forEach((v, j) => { шир[j] = Math.min(24, Math.max(шир[j] || 0, v.length)); }));
  const текст = т.map(р => р.map((v, j) => (v.length > 24 ? v.slice(0, 23) + '…' : v).padEnd(шир[j])).join('  ').trimEnd()).join('\n');
  const п = параметры({});
  const р = await отправить((п.подпись ? п.подпись + '\n' : '') + текст, {моноширинно: true});
  if(р.ок){ хранилище.положить('последняя', new Date().toLocaleString('ru-RU')); показатьНастройки(); }
  панель.сообщение(р.ок ? 'Отправлено: ' + в.лист + '!' + в.область + (строки.length === 60 ? ' (первые 60 строк)' : '') + '.' : 'Не отправилось: ' + р.почему + '.');
}

/* --- правила --- */
function правила(){ return хранилище.взять('правила', []) || []; }
function описать(п){ return п.лист + '!' + п.столбецИмя + ' ' + п.условие + (п.условие === 'пусто' ? '' : ' ' + п.порог) + ' → «' + п.шаблон.slice(0, 40) + (п.шаблон.length > 40 ? '…' : '') + '»'; }
function показатьПравила(){ панель.список('правила', правила().map(описать)); показатьНастройки(); }
const номерСтолбца = б => { let c = 0; for(const ch of б.toUpperCase()) c = c * 26 + ch.charCodeAt(0) - 64; return c - 1; };
async function шапкаЛиста(имя){
  const строки = await лист(имя).прочитать(ОБЛАСТЬ(0, 0, 0, 29));
  return (строки[0] || []).map(x => x == null ? '' : String(x).trim());
}
async function ДобавитьПравило(){
  const п = параметры({});
  const имя = (п.пЛист && String(п.пЛист).trim()) || (книга.выделение ? книга.выделение.лист : книга.листы[0]);
  let ст = String(п.пСтолбец || '').trim();
  if(!ст){ панель.сообщение('Укажите столбец условия: букву (C) или заголовок (Остаток).'); return; }
  let c;
  if(/^[A-Za-z]{1,3}$/.test(ст)) c = номерСтолбца(ст);
  else { const ш = await шапкаЛиста(имя); c = ш.findIndex(x => x.toLowerCase() === ст.toLowerCase()); if(c < 0){ панель.сообщение('На листе «' + имя + '» нет столбца с заголовком «' + ст + '».'); return; } }
  const условие = УСЛОВИЯ.includes(п.пУсловие) ? п.пУсловие : 'меньше';
  if(условие !== 'пусто' && String(п.пПорог == null ? '' : п.пПорог).trim() === ''){ панель.сообщение('Укажите порог: число, текст или число дней.'); return; }
  const шаблон = String(п.пШаблон || '').trim() || 'Строка {строка} листа {лист}: {значение}';
  const список = правила();
  список.push({id: Date.now().toString(36), лист: имя, столбец: c, столбецИмя: /^[A-Za-z]{1,3}$/.test(ст) ? ст.toUpperCase() : ст, условие, порог: String(п.пПорог == null ? '' : п.пПорог).trim(), шаблон});
  хранилище.положить('правила', список);
  показатьПравила();
  панель.сообщение('Правило добавлено. Пока книга открыта, при правках на листе «' + имя + '» оно проверяется само.');
}
function УдалитьПравило(){
  const п = параметры({}), выбор = п.правила;
  const список = правила();
  const i = список.findIndex(x => описать(x) === выбор);
  if(i < 0){ панель.сообщение('Выберите правило в списке.'); return; }
  список.splice(i, 1); хранилище.положить('правила', список); показатьПравила();
  панель.сообщение('Правило удалено.');
}
function число(v){ if(typeof v === 'number') return v; const n = parseFloat(String(v == null ? '' : v).replace(/\s/g, '').replace(',', '.')); return Number.isFinite(n) ? n : null; }
function датой(v){
  if(typeof v === 'number') return v;
  const м = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec(String(v || '').trim());
  return м ? Math.round((Date.UTC(+м[3], +м[2] - 1, +м[1]) - Date.UTC(1899, 11, 30)) / ДЕНЬ) : null;
}
function выполнено(пр, v){
  const x = число(v), порог = число(пр.порог);
  switch(пр.условие){
    case 'меньше': return x !== null && порог !== null && x < порог;
    case 'меньше или равно': return x !== null && порог !== null && x <= порог;
    case 'больше': return x !== null && порог !== null && x > порог;
    case 'больше или равно': return x !== null && порог !== null && x >= порог;
    case 'равно': return x !== null && порог !== null ? x === порог : String(v == null ? '' : v).trim().toLowerCase() === пр.порог.toLowerCase();
    case 'не равно': return x !== null && порог !== null ? x !== порог : String(v == null ? '' : v).trim().toLowerCase() !== пр.порог.toLowerCase();
    case 'содержит': return String(v == null ? '' : v).toLowerCase().includes(пр.порог.toLowerCase());
    case 'пусто': return v === null || v === undefined || v === '';
    case 'дата не позже чем через N дней': { const д = датой(v); return д !== null && порог !== null && д - сегодня() <= порог; }
  }
  return false;
}
function текстПравила(пр, шапка, ряд, r){
  return пр.шаблон.replace(/\{([^}]+)\}/g, (всё, имя) => {
    const к = имя.trim();
    if(к === 'лист') return пр.лист;
    if(к === 'строка') return String(r + 1);
    if(к === 'порог') return пр.порог;
    if(к === 'значение') return показ(ряд[пр.столбец], пр);
    let c = шапка.findIndex(x => x.toLowerCase() === к.toLowerCase());
    if(c < 0 && /^[A-Za-z]{1,3}$/.test(к)) c = номерСтолбца(к);
    return c >= 0 ? показ(ряд[c], пр) : всё;
  });
}
const показ = (v, пр) => v == null ? '' : пр.условие.startsWith('дата') && typeof v === 'number' ? ДМГ(v) : typeof v === 'number' ? v.toLocaleString('ru-RU') : String(v);
/* проверить строки листа по правилу; отправить по новым срабатываниям */
async function проверитьСтроки(пр, строкиНомера, {всеЗаново = false, ряды = null} = {}){
  const шапка = await шапкаЛиста(пр.лист);
  const уже = хранилище.взять('сработало', {}) || {};
  const новые = [];
  for(const r of строкиНомера){
    if(r === 0 && шапка.some(Boolean)) continue;
    const ряд = ряды ? (ряды[r] || []) : (await лист(пр.лист).прочитать(ОБЛАСТЬ(r, 0, r, Math.max(29, пр.столбец))))[0] || [];
    const ключ = пр.id + '|' + r, да = выполнено(пр, ряд[пр.столбец]);
    if(да && (!уже[ключ] || всеЗаново)){ новые.push(текстПравила(пр, шапка, ряд, r)); уже[ключ] = 1; }
    if(!да && уже[ключ]) delete уже[ключ];
  }
  хранилище.положить('сработало', уже);
  if(!новые.length) return 0;
  /* больше трёх — одним сообщением, чтобы не засыпать чат */
  const текст = новые.length <= 3 ? null : 'Сработало правило «' + описать(пр) + '» в ' + новые.length + ' строках:\n' + новые.slice(0, 30).map(x => '• ' + x).join('\n') + (новые.length > 30 ? '\n…' : '');
  const итоги = текст ? [await отправить(текст)] : await Promise.all(новые.map(x => отправить(x)));
  const плохо = итоги.find(x => !x.ок);
  if(плохо) сообщить('Уведомление не отправилось: ' + плохо.почему);
  else хранилище.положить('последняя', new Date().toLocaleString('ru-RU'));
  return новые.length;
}
async function Правка(){
  const п = книга.повод;
  if(!п || п.строение || п.откуда === 'плагин') return;
  for(const пр of правила()){
    const строки = [...new Set((п.клетки || []).filter(к => к.лист === пр.лист && к.столбец - 1 === пр.столбец).map(к => к.строка - 1))];
    if(строки.length) await проверитьСтроки(пр, строки);
  }
}
/* весь лист правила одним чтением (до 5000 строк): число строк снимка в фоновом потоке
   может отставать от книги, поэтому конец данных ищем сами */
async function весьЛист(пр){
  let ряды;
  try { ряды = await лист(пр.лист).прочитать(ОБЛАСТЬ(0, 0, 4999, Math.max(29, пр.столбец))); } catch(e){ return null; }
  let n = ряды.length;
  while(n > 0 && !(ряды[n - 1] || []).some(v => v !== null && v !== undefined && v !== '')) n--;
  return {ряды, номера: Array.from({length: n}, (_, i) => i)};
}
async function ПроверитьВсё(){
  const список = правила();
  if(!список.length){ панель.сообщение('Правил пока нет.'); return; }
  let всего = 0;
  for(const пр of список){
    const в = await весьЛист(пр); if(!в) continue;
    всего += await проверитьСтроки(пр, в.номера, {всеЗаново: true, ряды: в.ряды});
  }
  показатьНастройки();
  панель.сообщение(всего ? 'Отправлено уведомлений: ' + всего + '.' : 'Ни одно правило сейчас не срабатывает.');
}
/* сроки: при открытии книги раз в день — правила «дата не позже…» */
async function Старт(){
  показатьПравила();
  const день = сегодня();
  if(хранилище.взять('проверено', 0) === день) return;
  хранилище.положить('проверено', день);
  for(const пр of правила().filter(x => x.условие.startsWith('дата'))){
    const в = await весьЛист(пр); if(!в) continue;
    await проверитьСтроки(пр, в.номера, {ряды: в.ряды});
  }
}
